package com.example.library.service;
import com.example.library.model.Book; import com.example.library.repo.BookRepository; import org.springframework.cache.annotation.*; import org.springframework.data.domain.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class BookService {private final BookRepository repo;public BookService(BookRepository r){repo=r;}
 @Cacheable(value="books",key="#page+ '-' + #size + '-' + #q") public Page<Book> list(int page,int size,String q){Pageable p=PageRequest.of(Math.max(0,page),Math.min(Math.max(1,size),100),Sort.by("title").ascending());if(q==null||q.isBlank())return repo.findAll(p);return repo.search(q.trim(),p);}
 @CacheEvict(value="books",allEntries=true) @Transactional public Book create(Book b){b.setAvailableQuantity(b.getQuantity());return repo.save(b);}
 @CacheEvict(value="books",allEntries=true) @Transactional public Book update(Long id,Book input){Book b=repo.findById(id).orElseThrow(()->new IllegalArgumentException("Book not found"));int borrowed=b.getQuantity()-b.getAvailableQuantity();b.setTitle(input.getTitle());b.setAuthor(input.getAuthor());b.setIsbn(input.getIsbn());b.setCategory(input.getCategory());if(input.getQuantity()<borrowed)throw new IllegalArgumentException("Quantity cannot be lower than books currently borrowed");b.setQuantity(input.getQuantity());b.setAvailableQuantity(input.getQuantity()-borrowed);return repo.save(b);}
 @CacheEvict(value="books",allEntries=true) public void delete(Long id){Book b=repo.findById(id).orElseThrow(()->new IllegalArgumentException("Book not found"));if(b.getQuantity()!=b.getAvailableQuantity())throw new IllegalArgumentException("Cannot delete a book while copies are borrowed");repo.delete(b);}
}
